import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.2Gs1zKBA.js";const b=JSON.parse('{"title":"TCP与末端工具","description":"","frontmatter":{},"headers":[],"relativePath":"use-cases/tcp-tools.md","filePath":"use-cases/tcp-tools.md","lastUpdated":1794206918000}'),i={name:"use-cases/tcp-tools.md"};function l(o,t,n,r,c,p){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="tcp与末端工具" tabindex="-1">TCP与末端工具 <a class="header-anchor" href="#tcp与末端工具" aria-label="Permalink to &quot;TCP与末端工具&quot;">​</a></h1><p>本案例设置法兰到工具作用点的几何变换，并让 TCP 沿工具自身 Z 轴移动 2 cm，用于验证笛卡尔运动是否以实际工具作用点为参考。</p><div class="danger custom-block"><p class="custom-block-title">真机操作提示</p><p>错误的 TCP 会使工具实际路径偏离预期。运行前必须测量法兰到工具作用点的真实位姿，固定工具和线缆，清空完整运动空间，并确保紧急停止可用。示例结束时会失能机械臂；失能前必须可靠支撑机械臂及工具。</p></div><h2 id="演示目标" tabindex="-1">演示目标 <a class="header-anchor" href="#演示目标" aria-label="Permalink to &quot;演示目标&quot;">​</a></h2><p>示例依次完成以下流程：</p><ol><li>返回关节零位并进入非奇异演示姿态；</li><li>调用 <code>set_tcp()</code> 设置法兰 Z 轴正方向 15 cm 的 TCP；</li><li>读取当前 TCP 位姿，并沿工具自身 Z 轴移动 2 cm；</li><li>展示平行夹爪、灵巧手、吸盘和焊枪的 TCP 参数格式；</li><li>调用 <code>clear_tcp()</code> 恢复以法兰面为参考。</li></ol><p>示例中的 15 cm 只用于说明配置和坐标变换，不能替代对实际工具的测量。</p><h2 id="安装与准备" tabindex="-1">安装与准备 <a class="header-anchor" href="#安装与准备" aria-label="Permalink to &quot;安装与准备&quot;">​</a></h2><p>进入 <code>onero-sdk</code> 仓库并安装逆运动学依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/workspace/onero-sdk</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.[ik]&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>真机运行前还需要完成 <a href="/onerobot-A1/getting-started/hardware">CAN 接口配置与连接检查</a>，并确认：</p><ul><li>已测量法兰到工具作用点的真实位置和朝向；</li><li>工具、工件和线缆已可靠固定，工具运动方向上至少预留 5 cm；</li><li>已检查演示姿态和工具扫掠空间，不只检查 TCP 终点；</li><li>已单独配置工具与工件的总质量和合成重心；设置 TCP 不会自动设置负载。</li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数或设置</th><th>示例值</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>A1R</code></td><td>机械臂型号</td></tr><tr><td><code>channel</code></td><td><code>can0</code></td><td>真机 SocketCAN 通道</td></tr><tr><td>演示 TCP</td><td><code>[0, 0, 0.15] m</code></td><td>法兰到工具作用点的位置偏移</td></tr><tr><td>工具增量</td><td><code>[0, 0, 0.02, 0, 0, 0]</code></td><td>TCP 坐标系 Z 方向移动 2 cm</td></tr><tr><td><code>frame</code></td><td><code>tool</code></td><td>在当前工具坐标系中解释增量</td></tr><tr><td>运动时间</td><td><code>2.0 s</code></td><td>TCP 增量直线运动时间</td></tr><tr><td>IK 限位容差</td><td><code>0.02 rad</code></td><td>仅用于判断反馈是否超出模型限位</td></tr></tbody></table><h2 id="操作阶段" tabindex="-1">操作阶段 <a class="header-anchor" href="#操作阶段" aria-label="Permalink to &quot;操作阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>接口或阶段</th><th>操作含义</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>home()</code></td><td>返回软件定义的关节零位，不执行零点标定</td></tr><tr><td style="text-align:right;">2</td><td><code>movej()</code></td><td>进入非奇异 IK 演示姿态</td></tr><tr><td style="text-align:right;">3</td><td><code>set_tcp()</code></td><td>注册实际工具作用点相对法兰的位姿</td></tr><tr><td style="text-align:right;">4</td><td><code>get_pose(frame=&quot;base&quot;)</code></td><td>读取 TCP 在基座坐标系中的反馈位姿</td></tr><tr><td style="text-align:right;">5</td><td><code>movel(..., frame=&quot;tool&quot;)</code></td><td>沿工具自身 Z 轴执行 2 cm 相对运动</td></tr><tr><td style="text-align:right;">6</td><td><code>clear_tcp()</code></td><td>清除 TCP，恢复法兰参考</td></tr><tr><td style="text-align:right;">7</td><td><code>disable()</code></td><td>撤销电机保持力矩</td></tr></tbody></table><h2 id="真机运行" tabindex="-1">真机运行 <a class="header-anchor" href="#真机运行" aria-label="Permalink to &quot;真机运行&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">完整示例源码待补充</p><p><code>11_tool_frame.py</code> 的对应源码尚未补齐。以下命令和输出保留为演示记录，当前不能直接复现；取得并核对对应版本前，请勿据此运行真机。</p></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/11_tool_frame.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关键终端信息包括：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP 设置完成: position=[0, 0, 0.15]</span></span>
<span class="line"><span>目标：TCP 坐标系相对位移 [0.00, 0.00, 0.02] m</span></span>
<span class="line"><span>✓ TCP 已沿工具自身 Z 轴移动 2cm；请现场确认实际轨迹</span></span>
<span class="line"><span>TCP 已重置，运动指令以法兰面为参考</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>如果当前反馈超出 IK 模型限位，程序会打印对应关节、反馈值和 URDF 限位，不发送 TCP 运动。不得通过放宽容差或裁剪反馈值绕过检查。</p><h2 id="结果判断" tabindex="-1">结果判断 <a class="header-anchor" href="#结果判断" aria-label="Permalink to &quot;结果判断&quot;">​</a></h2><p>运行成功应同时满足：</p><ul><li>型号、CAN 通道、实际工具尺寸与源码配置一致；</li><li>工具作用点沿自身 Z 轴移动约 2 cm，末端姿态保持连续；</li><li>反馈位姿与现场观察方向一致，没有 IK、限位或通信异常；</li><li>演示结束后 TCP 被清除，机械臂在得到可靠支撑后正常失能。</li></ul><p>法兰在基座坐标系中的运动方向取决于当前姿态。若方向或路径不符合预期，应停止运动并检查 TCP 旋转、安装方向和坐标系，不能只修改正负号反复试错。</p><h2 id="末端工具边界" tabindex="-1">末端工具边界 <a class="header-anchor" href="#末端工具边界" aria-label="Permalink to &quot;末端工具边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>负责内容</th><th>不会自动完成</th></tr></thead><tbody><tr><td><code>set_tcp()</code></td><td>工具作用点的位置和朝向</td><td>夹爪通信、负载质量和重心</td></tr><tr><td><code>end_effector</code></td><td>末端工具驱动与动作控制</td><td>TCP 和负载配置</td></tr><tr><td><code>set_payload()</code></td><td>工具与工件总质量和合成重心</td><td>工具几何和夹爪动作</td></tr></tbody></table><h2 id="中断与安全状态" tabindex="-1">中断与安全状态 <a class="header-anchor" href="#中断与安全状态" aria-label="Permalink to &quot;中断与安全状态&quot;">​</a></h2><p>程序正常结束或发生异常时会尝试清除 TCP，并在机械臂仍使能时调用 <code>disable()</code>。<code>clear_tcp()</code> 只改变后续运动使用的几何参考，既不会停止当前运动，也不会让电机失能。</p><p>若工具运动方向异常、接近障碍物或出现失控趋势，应使用现场适用的紧急停止措施。不要把终端退出、<code>clear_tcp()</code> 或通信关闭视为安全停止。</p><p>完整参数说明见<a href="/onerobot-A1/tools/">TCP、负载与末端工具</a>。</p><p>完整示例源码：待补充（<code>examples/11_tool_frame.py</code>）。</p>`,33)])])}const u=e(i,[["render",l]]);export{b as __pageData,u as default};
